{
  "schema_version": 2,
  "claims": [
    {
      "id": "goal:longterm-stewardship",
      "kind": "goal",
      "statement": "Later coding-agent sessions should be able to use and correct accumulated product knowledge rather than reconstruct every consequential decision.",
      "authority_kind": "policy",
      "authority_ref": "docs/adr/0031-persistent-semantic-stewardship.md",
      "evidence_refs": [
        "file:docs/adr/0031-persistent-semantic-stewardship.md"
      ],
      "attributes": {
        "claim_ceiling": "Selected product direction; long-horizon benefit not yet demonstrated"
      }
    },
    {
      "id": "cap:semantic-queries",
      "kind": "capability",
      "statement": "The knowledge plane supplies bounded, source-linked queries over explicitly indexed claims, relationships, contradictions and recorded history.",
      "authority_kind": "policy",
      "authority_ref": "docs/adr/0031-persistent-semantic-stewardship.md",
      "evidence_refs": [
        "file:docs/persistent-semantic-stewardship-plan.md"
      ],
      "attributes": {
        "claim_ceiling": "Desired and partially implemented capability; no semantic truth or comparative benefit proven"
      }
    },
    {
      "id": "inv:source-boundary",
      "kind": "invariant",
      "statement": "A knowledge record must not silently promote extracted code facts, lexical associations, or agent hypotheses into owner intent or action authority.",
      "authority_kind": "policy",
      "authority_ref": "docs/adr/0031-persistent-semantic-stewardship.md",
      "evidence_refs": [
        "file:docs/adr/0031-persistent-semantic-stewardship.md"
      ]
    },
    {
      "id": "component:knowledge-store",
      "kind": "component",
      "statement": "The semantic knowledge store implements exact-revision SQLite indexing and evidence-preserving query operations.",
      "epistemic_status": "observed",
      "authority_kind": "code",
      "authority_ref": "src/sensemaking_skills/semantic_architecture/knowledge_store.py",
      "evidence_refs": [
        "file:src/sensemaking_skills/semantic_architecture/knowledge_store.py",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_retrieval.py"
      ],
      "attributes": {
        "claim_ceiling": "Source implementation, not test result or product-value proof",
        "owned_paths": [
          "src/sensemaking_skills/semantic_architecture/knowledge_store.py",
          "src/sensemaking_skills/semantic_architecture/knowledge_retrieval.py"
        ]
      }
    },
    {
      "id": "verification:knowledge-tests",
      "kind": "verification",
      "statement": "The semantic knowledge test module covers version identity, query shape, history, and authored-authority adversarial cases.",
      "epistemic_status": "observed",
      "authority_kind": "test",
      "authority_ref": "tests/test_semantic_knowledge.py",
      "evidence_refs": [
        "file:tests/test_semantic_knowledge.py"
      ],
      "attributes": {
        "claim_ceiling": "Test source exists; whether it passed is a separate CI observation"
      }
    },
    {
      "id": "lesson:grounding-waiver",
      "kind": "lesson",
      "statement": "The first target Grounding Pack required corrections to 20% of a ten-line spot check; acceptance was by explicit owner waiver, not a passing quality sample.",
      "authority_kind": "policy",
      "authority_ref": "docs/adr/0030-target-repository-grounding.md",
      "evidence_refs": [
        "file:docs/normal-use/grounding-pack-build-001.md"
      ],
      "attributes": {
        "scope": "Historical pilot quality finding; no inference about all future packs"
      }
    },
    {
      "id": "incident:query-omissions-baseline",
      "kind": "incident",
      "statement": "Source inspection at the recorded pre-repair main revision identified incomplete history/changes result slices incorrectly reported as untruncated, and impact traversals potentially exceeding a requested hop budget.",
      "authority_kind": "document",
      "authority_ref": "docs/normal-use/semantic-stewardship-episode-a-2026-10-15.md",
      "evidence_refs": [
        "file:docs/normal-use/semantic-stewardship-episode-a-2026-10-15.md"
      ],
      "attributes": {
        "examined_revision": "3a20bd80737b5df247791e4ff86256c0b4f54b83",
        "scope": "Historical source-inspection claim; pre-fix runtime reproduction not recorded; not a statement about repaired code"
      }
    },
    {
      "id": "inv:bounded-query-disclosure",
      "kind": "invariant",
      "statement": "Bounded knowledge queries must disclose omissions in every returned section and impact traversal must respect the declared edge-hop depth without pretending to establish causal dependencies.",
      "authority_kind": "delegated",
      "authority_ref": "docs/normal-use/semantic-stewardship-episode-a-2026-10-15.md",
      "evidence_refs": [
        "file:docs/normal-use/semantic-stewardship-episode-a-2026-10-15.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_store.py",
        "file:tests/test_semantic_knowledge.py"
      ],
      "attributes": {
        "scope": "Delegated engineering contract for a bounded query repair, not a new owner mandate",
        "claim_ceiling": "Qualified runtime behavior requires exact-head regression/hosted test evidence"
      }
    },
    {
      "id": "lesson:query-completeness-is-evidence",
      "kind": "lesson",
      "statement": "When a limited historical or change query silently reports completeness, absence of entries can be mistaken for absence of evidence; communicate omissions and totals before treating the result as architectural context.",
      "authority_kind": "document",
      "authority_ref": "docs/normal-use/semantic-stewardship-episode-a-2026-10-15.md",
      "evidence_refs": [
        "file:docs/normal-use/semantic-stewardship-episode-a-2026-10-15.md"
      ],
      "attributes": {
        "scope": "One source-grounded bug class; whether later independent agents use this lesson remains NOT TESTED"
      }
    },
    {
      "id": "inv:index-snapshot-vs-working-overlay",
      "kind": "invariant",
      "statement": "Exact-source index builds, orientation, rule checks and source audits read only a clean, pinned committed revision: the checked-out HEAD, or any local commit through a temporary worktree. Recall can query an existing committed index while the active working tree is dirty, but workspace context must disclose unindexed changes and must not promote that working overlay into indexed truth.",
      "authority_kind": "document",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_sources.py",
        "file:src/sensemaking_skills/semantic_architecture/worktree_context.py",
        "file:tests/test_semantic_knowledge_self_repo.py",
        "file:tests/test_semantic_workspace_impact.py"
      ],
      "attributes": {
        "scope": "Source-documented self-repository operating boundary; record is not a runtime invocation receipt",
        "claim_ceiling": "Source implementation and test coverage exist; pass claims require exact-head check receipts and do not establish independent-agent utility"
      }
    },
    {
      "id": "decision:workspace-impact-path-overlap",
      "kind": "decision",
      "statement": "Map active-workspace changes to reviewed indexed records inside knowledge-query by path-level overlap between changed paths since the indexed revision and each record's cited source fingerprints, instead of relaxing knowledge-audit's clean-HEAD byte comparison.",
      "authority_kind": "delegated",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
        "file:src/sensemaking_skills/semantic_architecture/worktree_context.py",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_retrieval.py",
        "file:tests/test_semantic_workspace_impact.py"
      ],
      "attributes": {
        "scope": "Delegated construction choice within ADR 0031; not an owner mandate",
        "claim_ceiling": "Same-session implementation and local tests; independent-agent use NOT TESTED"
      }
    },
    {
      "id": "alternative:dirty-tree-byte-audit",
      "kind": "alternative",
      "statement": "Rejected alternative: let knowledge-audit hash a dirty working tree, which would present uncommitted bytes as compared evidence and blur the indexed-snapshot versus working-overlay boundary.",
      "authority_kind": "delegated",
      "authority_ref": "docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
      "evidence_refs": [
        "file:docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_sources.py"
      ],
      "attributes": {
        "disposition": "rejected",
        "scope": "Rejected for the current construction phase; revisit only with a design that keeps overlay evidence explicitly unindexed"
      }
    },
    {
      "id": "lesson:uncited-change-is-coverage-gap",
      "kind": "lesson",
      "statement": "A changed file that no reviewed record cites is a knowledge coverage gap, not evidence that the change has no semantic effect; workspace-impact first exposed this when the query modules knowledge_retrieval.py and semantic_cli.py changed without any citing record.",
      "authority_kind": "document",
      "authority_ref": "docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
      "evidence_refs": [
        "file:docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_retrieval.py",
        "file:tests/test_semantic_workspace_impact.py"
      ],
      "attributes": {
        "scope": "One same-session observation; whether later agents apply it is NOT TESTED",
        "operationalized_by": "workspace-impact uncited_changed_paths / uncited_changed_path_total list changed paths no reviewed record cites (2026-10-21 construction follow-up); a listed path is a coverage gap to inspect, not a semantic-effect judgment"
      }
    },
    {
      "id": "incident:shared-authored-pack-fingerprint-fanout",
      "kind": "incident",
      "statement": "During the 2026-10-21 self-repository stewardship episode, an edit to the shared authored JSON pack was reported to flag all 19 prior reviewed pack records in knowledge-audit and list 15 changed claims in changes; source inspection confirms whole-pack fingerprints can produce record-level change noise without proving each claim's authored meaning changed.",
      "authority_kind": "document",
      "authority_ref": "docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
      "evidence_refs": [
        "file:docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_sources.py",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_store.py"
      ],
      "attributes": {
        "scope": "Agent-reported source-revision comparison from PR #560 self-dogfooding; counts are not independently reproduced in this follow-up",
        "claim_ceiling": "Mechanism is supported by current source inspection; source-byte flags remain valid and specific semantic false-positive counts are not established",
        "status": "OPEN for conservative whole-pack audit by design; integrated PR #561 (db6b546f) adds change_classification to interpret the fanout in changes, while raw delta IDs keep full-payload semantics"
      }
    },
    {
      "id": "lesson:distinguish-provenance-content-and-meaning",
      "kind": "lesson",
      "statement": "Distinguish whole-file provenance drift, changes to individual authored record fields, changes to independently cited evidence, and source-verified changes in architectural meaning before concluding that a reviewed knowledge claim was revised.",
      "authority_kind": "document",
      "authority_ref": "docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
      "evidence_refs": [
        "file:docs/normal-use/semantic-steward-workspace-impact-2026-10-21.md",
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_sources.py",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_store.py"
      ],
      "attributes": {
        "scope": "Source-grounded interpretation hygiene; integrated PR #561 implements additive classification of indexed record differences without automatic truth",
        "claim_ceiling": "Source-grounded guidance, not a claim that semantic changes can currently be detected automatically"
      }
    },
    {
      "id": "decision:granular-indexed-delta-classification",
      "kind": "decision",
      "statement": "Preserve the existing raw changes ID lists and source-byte audit, while adding source-fingerprint-based classifications of Git-authored record fields, shared-container provenance, independent supporting evidence, and NOT_ASSESSED cases to indexed revision comparisons.",
      "authority_kind": "delegated",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_retrieval.py",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_store.py",
        "file:tests/test_semantic_change_classification.py"
      ],
      "attributes": {
        "scope": "Bounded PR #561 construction choice, integrated as db6b546f; no owner-level policy change, no SQLite schema migration",
        "claim_ceiling": "Integrated source implementation and regression tests (post-merge CI passed at db6b546f); no semantic truth or independent agent reuse inferred"
      }
    },
    {
      "id": "verification:granular-delta-classification-tests",
      "kind": "verification",
      "statement": "The semantic change-classification test module contains Git-revision fixtures for shared authored packs, supporting evidence changes, incomplete fingerprints, provenance-only output, bounded totals and CLI compatibility.",
      "authority_kind": "test",
      "authority_ref": "tests/test_semantic_change_classification.py",
      "evidence_refs": [
        "file:tests/test_semantic_change_classification.py",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_retrieval.py"
      ],
      "attributes": {
        "scope": "Test definitions and coverage only; actual test passes require revision-pinned execution receipts"
      }
    },
    {
      "id": "verification:clean-index-tests",
      "kind": "verification",
      "statement": "Regression tests enforce the clean pinned committed HEAD boundary for knowledge snapshot builds.",
      "authority_kind": "test",
      "authority_ref": "tests/test_semantic_knowledge_self_repo.py",
      "evidence_refs": [
        "file:tests/test_semantic_knowledge_self_repo.py"
      ],
      "epistemic_status": "declared"
    },
    {
      "id": "lesson:installed-skill-currency-includes-references",
      "kind": "lesson",
      "statement": "An installed Skill copy is current only if its references match as well as its SKILL.md: the compact using-sensemaking core loads load-bearing rules from references on demand, so a matching entrypoint with stale references changes agent behavior.",
      "authority_kind": "code",
      "authority_ref": "scripts/repo_probes.py",
      "evidence_refs": [
        "file:scripts/repo_probes.py",
        "file:scripts/probe_skill_distribution.py",
        "file:INSTALLATION.md",
        "file:skills/using-sensemaking/SKILL.md"
      ],
      "epistemic_status": "observed",
      "attributes": {
        "decision_changed": "Whether a host's installed Sensemaking Skill can be reported as current after a merge.",
        "claim_ceiling": "Observed on one scratch setup-skills install; hosted or remote Skill surfaces are not covered by the file probe. The probe's default root is ~/.agents/skills, not the Claude Code root ~/.claude/skills; a Claude Code install is verified only when --installed-dir names its root, and a verdict covers only the root probed."
      }
    },
    {
      "id": "decision:index-from-temporary-worktree",
      "kind": "decision",
      "statement": "--temporary-checkout on knowledge-build, knowledge-orient, knowledge-check-rules and knowledge-audit reads the named commit from a temporary detached git worktree outside the checkout, then removes it, so a dirty active checkout (for example an untracked session receipt) or another local commit needs no hand-made clean clone. The flag is opt-in and the clean-source check is unchanged rather than exempting untracked files or reading dirty bytes. Hooks and configured external filters are disabled, and a commit that assigns a filter to a tracked path is refused. Orient, check-rules and audit report the unread active checkout in source_checkout and active_checkout.",
      "authority_kind": "delegated",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_sources.py",
        "file:src/sensemaking_skills/semantic_cli.py"
      ],
      "attributes": {
        "scope": "Delegated construction choice within ADR 0031; not an owner mandate",
        "claim_ceiling": "knowledge-build: manual CLI probes on one shallow cloud checkout and disposable repositories. Orient, check-rules and audit: real-CLI probes on one Windows host, on scratch repositories and this repository; unit tests NOT_RUN; independent-agent use NOT TESTED",
        "revision_note": "2026-11-10: extended from knowledge-build to the three other commit-pinned commands"
      }
    },
    {
      "id": "alternative:shared-clone-checkout",
      "kind": "alternative",
      "statement": "Rejected alternative: materialize target-ref with git clone --shared. For a shallow source Git ignored --shared and copied objects without an alternates file, and a local clone carries only the source's local refs, so a commit reachable only through remote-tracking refs was absent.",
      "authority_kind": "delegated",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md"
      ],
      "attributes": {
        "disposition": "rejected",
        "scope": "Observed on this repository's shallow cloud checkout on 2026-10-28; revisit only if shallow sources need not be supported"
      }
    },
    {
      "id": "alternative:automatic-temporary-checkout-fallback",
      "kind": "alternative",
      "statement": "Rejected alternative: have knowledge-build, knowledge-orient, knowledge-check-rules and knowledge-audit fall back to a temporary checkout automatically whenever the active checkout is dirty. It would change a fail-closed default that hosted tests pin, pay for a full checkout the caller did not ask for, and let a caller miss that uncommitted edits were not read.",
      "authority_kind": "delegated",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:src/sensemaking_skills/semantic_cli.py",
        "file:tests/test_architecture_rule_checker.py",
        "file:tests/test_repository_bootstrap.py"
      ],
      "attributes": {
        "disposition": "rejected",
        "scope": "Rejected 2026-11-10 for the four explicit-identity commands. workspace-query is a different contract: it resolves and materializes the commit itself and reports that in workspace_index.build_source (decision:workspace-query-derived-commit-index). Revisit if agents are observed to skip audit or rule checks because the refusal hint does not lead them to the flag"
      }
    },
    {
      "id": "alternative:read-committed-bytes-from-git-objects",
      "kind": "alternative",
      "statement": "Deferred alternative: read committed bytes from Git objects instead of checking the commit out, for index building (including the first call of workspace-query) and for orient, check-rules and audit. It would remove the checkout cost, roughly 10 s of a 15 to 20 s first call on the development host. The builder reads and fingerprints files from a checkout, and its tracked-file, symlink and filter checks assume one; source fingerprints are taken from checked-out bytes, which Git can convert (line endings, filters), so an object reader would be a second byte path that has to agree with every index already built.",
      "authority_kind": "delegated",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_sources.py",
        "file:src/sensemaking_skills/workspace_knowledge.py"
      ],
      "attributes": {
        "disposition": "deferred",
        "scope": "Deferred 2026-11-10 for how a commit is materialized, by the temporary-checkout change and by the workspace-query change; the two records were merged into this one during integration. That object bytes differ from checkout bytes is inferred from the source and was not run; lesson:separate-clone-changes-audited-bytes observed the related fact that checked-out bytes vary with Git configuration",
        "revisit_when": "First-call latency or the checkout cost is shown to keep agents from querying or checking, and index building and the readers can move to the same reader in one change; or snapshots must be byte-identical across platforms"
      }
    },
    {
      "id": "lesson:separate-clone-changes-audited-bytes",
      "kind": "lesson",
      "statement": "A separate clone is not a neutral clean checkout for knowledge-audit. Source fingerprints are taken from checked-out bytes, after any line-ending conversion, so in a clone made under another core.autocrlf setting cited text files read as changed. A temporary worktree of the same repository uses that repository's configuration and checks out the same bytes as its ordinary checkout; the flag does not make differently configured clones agree.",
      "authority_kind": "document",
      "authority_ref": "docs/semantic-architecture/persistent-knowledge-cli.md",
      "evidence_refs": [
        "file:docs/semantic-architecture/persistent-knowledge-cli.md",
        "file:src/sensemaking_skills/semantic_architecture/knowledge_store.py"
      ],
      "epistemic_status": "observed",
      "attributes": {
        "scope": "Observed on one Windows host on 2026-11-10, auditing an index of commit 53b667c1 at commit baaec6b9: 442 of 442 records reported changed from a clone made under the system default core.autocrlf=true, with and without --temporary-checkout, against 139 of 442 from a worktree of the repository. An independent reviewer reproduced both counts. Other conversions (filters, working-tree-encoding) not probed",
        "decision_changed": "Whether an audit run from a hand-made clone can be trusted, and why --temporary-checkout materializes a worktree rather than a clone"
      }
    },
    {
      "id": "lesson:console-guard-literal-print-arguments-only",
      "kind": "lesson",
      "statement": "The ASCII console guard (tests/test_console_output_ascii_only.py) inspects only string literals written directly inside print() calls, so non-ASCII text that reaches print() through a variable passes it. On this Windows host a redirected stdout is cp1252, and printing U+2705 raises UnicodeEncodeError (probed). scripts/test-validators.py and scripts/analyze-run-failures.py printed report text that carried such glyphs, and only the cli.py main() entry point escapes unencodable output, so scripts/ entrypoints depend on ASCII source discipline alone.",
      "authority_kind": "document",
      "authority_ref": "CLAUDE.md",
      "evidence_refs": [
        "file:tests/test_console_output_ascii_only.py",
        "file:scripts/test-validators.py",
        "file:scripts/analyze-run-failures.py",
        "file:scripts/portfolio-orchestrator.py",
        "file:src/sensemaking_skills/cli.py"
      ],
      "epistemic_status": "observed",
      "attributes": {
        "scope": "Source inspection and a stdout-encoding probe on one Windows host at 0b1df456. The two scripts were not executed (local test-runner execution is withheld by the construction policy). Whether later agents apply this lesson is NOT TESTED.",
        "operationalized_by": "Not operationalized by a new check. The guard is unchanged; non-ASCII glyphs were replaced in the three scripts' console-reachable report text. scripts/workflow-runtime.py was not assessed for console-reachable text.",
        "staleness_condition": "Stale when the guard learns to follow data flow into print(), when scripts/ gains an escape layer, or when the named print paths change."
      }
    },
    {
      "id": "decision:proposal-check-existence-only-endpoints",
      "kind": "decision",
      "statement": "knowledge-proposal-check checks an endpoint whose authored record lives in another file for existence and kind only. That record's own attributes and rule scope are validated where its file is read, so a proposal is not rejected for another file's defect. Kind-dependent relation checks still apply to the endpoint.",
      "authority_kind": "delegated",
      "authority_ref": "docs/adr/0031-persistent-semantic-stewardship.md",
      "evidence_refs": [
        "file:src/sensemaking_skills/semantic_architecture/stewardship_validation.py",
        "file:src/sensemaking_skills/semantic_architecture/knowledge.py"
      ],
      "attributes": {
        "scope": "Delegated construction choice within ADR 0031; not an owner mandate",
        "claim_ceiling": "Source inspection and proposal-check on this proposal before and after the change; unit tests NOT_RUN by construction policy; no independent-agent use observed",
        "staleness_condition": "Superseded by the 2026-11-10 file-scoped validation contract; retained as the historical existence-only endpoint choice."
      },
      "epistemic_status": "superseded"
    },
    {
      "id": "alternative:carry-external-attributes-into-placeholders",
      "kind": "alternative",
      "statement": "Rejected alternative: copy an external record's attributes into proposal placeholders so v2 checks run on real data. It reports another file's defect as a proposal failure, and a rule whose scope is given by a relation in a third file would still fail the scope check.",
      "authority_kind": "delegated",
      "authority_ref": "docs/adr/0031-persistent-semantic-stewardship.md",
      "evidence_refs": [
        "file:src/sensemaking_skills/semantic_architecture/stewardship_validation.py"
      ],
      "attributes": {
        "disposition": "rejected",
        "scope": "Considered at 465420ed while choosing the proposal-check repair recorded by the 2026-10-30 console-ASCII receipt"
      }
    },
    {
      "id": "component:workflow-installation-availability",
      "kind": "component",
      "statement": "The workflow installation-availability module distinguishes which required Skills are present in an explicitly grounded installed root from workflow liveness and execution authorization; it does not load host instructions or select semantic work.",
      "authority_kind": "code",
      "authority_ref": "src/sensemaking_skills/workflow_availability.py",
      "evidence_refs": [
        "file:src/sensemaking_skills/workflow_availability.py",
        "file:docs/product-management/distribution-profile-contract.md",
        "file:artifacts/history/2026-11-01-graph-activation-architectural-synthesis.md"
      ],
      "epistemic_status": "observed",
      "attributes": {
        "owned_paths": [
